import json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[2]
r=json.loads((ROOT/'results/los-navigation-heuristic-combat.json').read_text())
assert len(r['results'])==7
lines=['# Learned LOS navigation with heuristic encounters','','Frozen rest/sleep seed-0 model after '+str(r['trained_decisions'])+' training decisions. No retraining. Same 1,024 starting validation episodes (32 layouts × 32 placements), 24 ordinary enemies, 15×15 wall-blocked LOS, LOS-gated waking, and 2,048 policy decisions. Rest may consume multiple physical turns.','','## Ownership rules','','- Learned-only: original model chooses every action.','- Awake-trigger hybrid: start heuristic ownership when at least one **visible awake** enemy exists; keep ownership until **no enemy is visible**, including sleepers.','- Visible-trigger hybrid: start ownership at any visible enemy, including sleeping enemies; end when no enemy is visible.','- While engaged, use the LOS-only seek-and-destroy + hallway retreat + awake-enemy waiting policy. It attacks adjacent enemies, waits for awake enemies when none is adjacent, and may retreat to the original strict known-hallway targets. Sleeping-only enemies may be approached.','- Outside encounters, the learned policy controls everything, including whether to rest. There is no extra forced healing rule.','- The heuristic remembers observed terrain during learned navigation. Retreat cannot secretly initiate while the model owns control. When enemies leave sight, the retreat state resets.','- Heuristic-only: the same encounter policy also handles exploration and rest.','- No native privileged enemy-location pursuit is used in any arm. All policies receive the original LOS observation and action mask.','','Sampled and greedy refer only to model decisions. Sampling continues across the full batch on each decision, including overridden actions, matching the original evaluation RNG consumption convention. Simulator RNG and initial states are matched; later trajectories and combat RNG consumption can diverge.','','## Results','','| Policy | Clears | Deaths | Timeouts | Mean physical turns | Clear-only turns |','|---|---:|---:|---:|---:|---:|']
for name,result in r['results'].items():
 m=result['metrics'];lines.append(f"| {name} | {m['clears']} ({100*m['clear_rate']:.2f}%) | {m['deaths']} | {m['timeouts']} | {m['turns']:.1f} | {m['clear_only_turns']:.1f} |")
lines+=['','| Hybrid | Mean model decisions | Mean heuristic decisions | Mean encounters | Mean rest uses |','|---|---:|---:|---:|---:|']
for name,result in r['results'].items():
 if name.startswith(('awake','visible')):
  m=result['metrics'];lines.append(f"| {name} | {m['learned_decisions']:.1f} | {m['heuristic_decisions']:.1f} | {m['encounters']:.1f} | {m['rest_uses']:.1f} |")
lines+=['','## Paired outcomes versus the corresponding learned-only policy','','| Hybrid | Newly clear | Previously clear, now fails |','|---|---:|---:|']
for name,result in r['results'].items():
 if name.startswith(('awake','visible')):
  mode=name.split('-')[1];base=r['results']['learned-'+mode]['episodes'];eps=result['episodes']
  gain=sum(not a['clear'] and b['clear'] for a,b in zip(base,eps));loss=sum(a['clear'] and not b['clear'] for a,b in zip(base,eps));lines.append(f'| {name} | {gain} | {loss} |')
lines+=['','## Validation and limits','','Both learned-only controls exactly reproduce saved sampled/greedy clear rate, death rate, timeout rate, kills and physical turns. Heuristic-only exactly reproduces the prior LOS-only waiting/retreat result on the same metrics. All selected actions pass the original mask; all episodes terminate. Encounter-gate checks cover awake versus sleeping triggers, persistence while sleepers remain, reset with no visible enemies, and inactive worlds. Checkpoint, policy sources and simulator library hashes are recorded in the raw artifact.','','These are evaluation-time interventions on one frozen model and a reused validation panel. The comparison tests whether replacing its encounter decisions helps; it does not measure the performance of a model trained specifically for navigation with heuristic combat. A change in clear rate cannot be attributed to attacks alone: retreat, waiting, target selection, pursuit of sleepers and the states handed back to navigation change together.','','Evaluation wall seconds (all seven arms): '+f"{sum(v['metrics']['evaluation_seconds'] for v in r['results'].values()):.1f}"+'. No training time incurred.','','```sh','gpu-d1/.venv/bin/python gpu-d1/diagnostics/seek-destroy-los/run_hybrid.py','gpu-d1/.venv/bin/python gpu-d1/diagnostics/seek-destroy-los/report_hybrid.py','```','','Raw artifact: `results/los-navigation-heuristic-combat.json`.','']
(ROOT/'LOS-NAVIGATION-HEURISTIC-COMBAT.md').write_text('\n'.join(lines))
